import Header from '../components/Header';
import Footer from '../components/Footer';
import '../index.css';
import { Playfair_Display, Lato } from 'next/font/google';

const playfair = Playfair_Display({
    subsets: ['latin'],
    variable: '--font-heading',
    display: 'swap',
});

const lato = Lato({
    subsets: ['latin'],
    weight: ['300', '400', '700'],
    variable: '--font-body',
    display: 'swap',
});

export const metadata = {
    title: 'Advocate RK & Associates | Expert Legal Counsel in Roorkee',
    description: 'Top criminal advocate in Roorkee and Haridwar. RK Associates specializes in Criminal Defense, Divorce, Property Litigation, and Cheque Bounce cases.',
    keywords: 'Advocate RK, RK Associates, Criminal Lawyer Roorkee, Legal Counsel Haridwar, Divorce Lawyer, Property Litigation',
}

export default function RootLayout({ children }) {
    return (
        <html lang="en" className={`${playfair.variable} ${lato.variable}`}>
            <head>
                <link rel="icon" href="/favicon.svg" type="image/svg+xml" />
            </head>
            <body>
                <Header />
                <main>{children}</main>
                <Footer />
            </body>
        </html>
    )
}
